known_edges = [(1,9), (2,9), (6,9), (3,10), (5,7), (2,8), (7,9), (4,6)]
known_edges = [tuple(sorted(e)) for e in known_edges]
edges = set(known_edges)

for u in range(11):
    for v in range(u + 1, 11):
        if len(edges) < 32:
            edges.add((u, v))

sorted_edges = sorted(list(edges))
flattened = []
for u, v in sorted_edges:
    flattened.extend([u, v])

print(flattened)
print("Number of edges:", len(sorted_edges))
